1038	      ctx.on(resyncBtn, "click", () => {
1039	        scrollFollow.resume();
1040	        if (currentWordIndex >= 0 && textContainer) {
1041	          const el = textContainer.querySelector<HTMLElement>(
1042	            wordSelector(currentWordIndex),
1043	          );
1044	          el?.scrollIntoView({ behavior: "smooth", block: "center" });
1045	        }
1046	      });
1047	    }
1048	
1049	    if (textContainer && "IntersectionObserver" in window) {
1050	      intersectionObserver = new IntersectionObserver(
1051	        (entries) => {
1052	          for (const entry of entries) {
1053	            if (entry.isIntersecting && scrollFollow.get().autoScrollPaused) {
1054	              scrollFollow.resume();
1055	            }
1056	          }
1057	        },
1058	        { threshold: 0.5 },
1059	      );
1060	      ctx.onDestroy(() => intersectionObserver?.disconnect());
1061	    }
1062	
1063	    ctx.bindStore(scrollFollow, (s) => {
1064	      if (!resyncBtn) return;
1065	      resyncBtn.classList.toggle("hidden", !s.autoScrollPaused);
1066	    });
1067	
1068	    // Word menu actions
1069	    ctx.on(window, "word-action", (detail) => {
1070	      if (detail.kind === "play") seekToWordIndex(detail.index);
1071	    });
1072	
1073	    // Speed badge cycle
1074	    if (speedBadge) ctx.on(speedBadge, "click", () => cycleSpeed("up"));
1075	
