1077	    ctx.on(window, "audio:toggle-playback", togglePlayback);
1078	    ctx.on(window, "audio:toggle-mute", () => {
1079	      audio.muted = !audio.muted;
1080	    });
1081	    ctx.on(window, "audio:change-speed", ({ direction }) =>
1082	      cycleSpeed(direction),
1083	    );
1084	
1085	    // Manual chapter nav (floating-pill buttons + keyboard arrows). These
1086	    // dispatch a window event instead of phx-click="next_chapter" while
1087	    // the audio player is mounted so we can do a same-<audio>-element src
1088	    // swap instead of letting the server's push_patch leave us playing
1089	    // the previous chapter. When the next/prev chapter has no audio yet,
1090	    // goTo*Chapter returns false and we fall back to the server-owned
1091	    // path so the user can still navigate to audio-less chapters.
