1098	      if (!goToPrevChapter()) ctx.pushEvent("prev_chapter", {});
1099	    });
1100	
1101	    // Final cleanup not covered by ctx.on. Important: do NOT pause the
1102	    // audio or revoke its current blob URL here. Destroy fires on LV
1103	    // reconnect/re-mount (long phone sleep → server LV process times out
1104	    // → client re-mount on wake) — and the <audio> element survives
1105	    // (phx-update="ignore"). Pausing or revoking would interrupt the
1106	    // user's listening session at exactly the moment they wake the phone
1107	    // hoping playback continues. If the player is genuinely going away
1108	    // (user navigates off the reader), the <audio> element gets removed
