23	  TDataset = Record<string, string | undefined>,
24	> {
25	  readonly el: TEl;
26	  readonly dataset: Readonly<TDataset>;
27	
28	  on<K extends keyof HTMLElementEventMap>(
29	    target: HTMLElement | Document,
30	    event: K,
31	    handler: (e: HTMLElementEventMap[K]) => void,
32	    opts?: AddEventListenerOptions,
33	  ): void;
34	  on<K extends keyof WindowEventMap>(
35	    target: Window,
36	    event: K,
37	    handler: (e: WindowEventMap[K]) => void,
38	    opts?: AddEventListenerOptions,
39	  ): void;
40	  on<K extends keyof ReadaloudWindowEvents>(
41	    target: Window,
42	    event: K,
43	    handler: ReadaloudWindowEvents[K] extends undefined
44	      ? () => void
45	      : (detail: ReadaloudWindowEvents[K]) => void,
46	  ): void;
47	
48	  dispatch<K extends keyof ReadaloudWindowEvents>(
49	    event: K,
50	    ...detail: WindowEventDetail<K>
51	  ): void;
52	
53	  pushEvent<K extends keyof ReadaloudPushEvents>(
54	    event: K,
55	    ...payload: PushEventArgs<K>
56	  ): void;
57	
58	  handleEvent<K extends keyof ReadaloudHandleEvents>(
59	    event: K,
60	    handler: (payload: ReadaloudHandleEvents[K]) => void,
61	  ): void;
62	
63	  onDestroy(fn: () => void): void;
64	  onUpdate(fn: () => void): void;
65	
