  // require shadowing lib.dom.d.ts — not worth it. Misuse fails silently
  // (DOM no-ops on a wrong-target listener); we accept this trade-off.
  bindElement<K extends keyof HTMLElementEventMap>(
    target: HTMLElement,
    events: readonly K[],
    apply: () => void,
  ): void;
