    when is_list(raw) do
  %{dropped: dropped} = ReadaloudReader.observe_batch!(socket.assigns.book.id, raw)

  :telemetry.execute(
    [:readaloud, :progress, :flush],
    %{count: length(raw), dropped: length(dropped)},
    %{transport: "ws"}
  )

  {:noreply, socket}
end

