import puppeteer from "puppeteer";

const BASE_URL = "http://localhost:4000";
const browser = await puppeteer.launch({
	headless: true,
	executablePath: "/usr/bin/google-chrome",
	args: ["--no-sandbox", "--disable-setuid-sandbox"],
});
const page = await browser.newPage();
await page.setViewport({ width: 1280, height: 800 });
page.on("console", (msg) => {
	const t = msg.text();
	if (t.includes("[autoplay") || t.includes("error") || t.includes("Error"))
		console.log("BROWSER:", t.slice(0, 300));
});
page.on("pageerror", (err) => console.log("PAGEERROR:", String(err)));

await page.goto(`${BASE_URL}/books/1/read/1?nav=internal`, {
	waitUntil: "domcontentloaded",
});
await page.waitForSelector("[data-phx-session].phx-connected", {
	timeout: 10000,
});
await page.waitForSelector("#chapter-text", { timeout: 10000 });
await page.waitForFunction(
	() => {
		const a = document.getElementById("audio-element");
		return a?.src && a.src.length > 0;
	},
	{ timeout: 5000 },
);

await page.click("#play-pause-btn");
await new Promise((r) => setTimeout(r, 1000));

const pre = await page.evaluate(() => {
	const player = document.getElementById("audio-player");
	const bar = document.getElementById("chapter-bar");
	const a = document.getElementById("audio-element");
	return {
		url: location.pathname,
		paused: a?.paused,
		src: a?.src,
		datasetChapter: player?.dataset.chapterId,
		nextChapterId: player?.dataset.nextChapterId,
		barChapters: bar?.dataset.chapters,
		barCurrentIndex: bar?.dataset.currentIndex,
		barClasses: bar?.className,
	};
});
console.log("PRE:", JSON.stringify(pre, null, 1));

// open pill + bar
await page.mouse.move(640, 10);
await new Promise((r) => setTimeout(r, 400));
await page.click("#chapter-indicator");
await new Promise((r) => setTimeout(r, 400));

const barState = await page.evaluate(() => {
	const bar = document.getElementById("chapter-bar");
	const pill = bar?.querySelector('[data-chapter-pill="1"]');
	const rect = pill?.getBoundingClientRect();
	return {
		barClasses: bar?.className,
		pillRect: rect ? { x: rect.x, y: rect.y, w: rect.width, h: rect.height } : null,
		topElementAtPill: rect
			? document.elementFromPoint(rect.x + rect.width / 2, rect.y + rect.height / 2)?.outerHTML?.slice(0, 120)
			: null,
	};
});
console.log("BAR:", JSON.stringify(barState, null, 1));

await page.click('[data-chapter-pill="1"]');
await new Promise((r) => setTimeout(r, 3000));

const post = await page.evaluate(() => {
	const player = document.getElementById("audio-player");
	const a = document.getElementById("audio-element");
	return {
		url: location.pathname,
		src: a?.src,
		paused: a?.paused,
		datasetChapter: player?.dataset.chapterId,
	};
});
console.log("POST:", JSON.stringify(post, null, 1));

await browser.close();

