import puppeteer from "puppeteer";

const browser = await puppeteer.launch({
	headless: true,
	executablePath: "/usr/bin/google-chrome",
	args: ["--no-sandbox", "--disable-setuid-sandbox"],
});
const page = await browser.newPage();
await page.setViewport({ width: 1280, height: 800 });
page.on("console", (msg) => console.log("BROWSER:", msg.text().slice(0, 200)));
page.on("pageerror", (err) => console.log("PAGEERROR:", String(err)));

const cdp = await page.createCDPSession();
await cdp.send("Network.enable");
cdp.on("Network.webSocketFrameSent", ({ response }) => {
	const p = response.payloadData || "";
	if (p.includes("jump_to_chapter") || p.includes("event"))
		console.log("WS-SENT:", p.slice(0, 220));
});

await page.goto("http://localhost:4000/books/1/read/1?nav=internal", {
	waitUntil: "domcontentloaded",
});
await page.waitForSelector("[data-phx-session].phx-connected", { timeout: 10000 });
await page.waitForSelector("#chapter-text", { timeout: 10000 });
await new Promise((r) => setTimeout(r, 1500));

await page.mouse.move(640, 10);
await new Promise((r) => setTimeout(r, 400));
await page.click("#chapter-indicator");
await new Promise((r) => setTimeout(r, 400));

// Native-listener probe: does a direct DOM click event reach any handler?
await page.evaluate(() => {
	const pill = document.querySelector('[data-chapter-pill="1"]');
	pill.addEventListener("click", () => console.log("PROBE: native click fired on pill"));
});
await page.click('[data-chapter-pill="1"]');
await new Promise((r) => setTimeout(r, 2500));
console.log("URL-AFTER:", await page.evaluate(() => location.pathname));
await browser.close();
EOF
